<div class="d-flex flex-wrap justify-content-between gap-2 align-items-center mb-3"><div><a href="<?= url('/invoices') ?>" class="text-decoration-none">← Invoices</a><p class="mb-0 text-secondary"><?= e($invoice['customer_name']) ?> · due <?= e($invoice['due_date']??'-') ?></p></div><div class="d-flex gap-2"><button class="btn btn-outline-secondary collab-btn" data-entity="invoice" data-id="<?= $invoice['id'] ?>"><i class="bi bi-chat-left-text"></i> Notes & Docs</button><a target="_blank" class="btn btn-outline-secondary" href="<?= url('/print/invoice/'.$invoice['id']) ?>"><i class="bi bi-printer"></i> Print/PDF</a><span class="status-badge <?= $invoice['status']==='Paid'?'success':($invoice['status']==='Overdue'?'danger':'') ?>"><?= e($invoice['status']) ?></span></div></div>
<div class="row g-3"><div class="col-lg-8"><div class="card-panel mb-3"><div class="table-responsive"><table class="table"><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th class="text-end">Unit Price</th><th class="text-end">Total</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['description']) ?></td><td><?= e($i['quantity']) ?></td><td><?= e($i['unit']) ?></td><td class="text-end"><?= e(money($i['unit_price'])) ?></td><td class="text-end"><?= e(money($i['line_total'])) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th colspan="4" class="text-end">Total</th><th class="text-end fs-5"><?= e(money($invoice['total'])) ?></th></tr><tr><th colspan="4" class="text-end">Paid</th><th class="text-end text-success"><?= e(money($invoice['paid'])) ?></th></tr><tr><th colspan="4" class="text-end">Balance</th><th class="text-end"><?= e(money($invoice['balance'])) ?></th></tr></tfoot></table></div></div><div class="card-panel"><h3 class="h6">Payment History</h3><table class="table"><thead><tr><th>Date</th><th>Method</th><th>Reference</th><th>Recorded by</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?= e($p['payment_date']) ?></td><td><?= e($p['payment_method']) ?></td><td><?= e($p['reference']??'-') ?></td><td><?= e($p['user_name']??'-') ?></td><td class="text-end"><?= e(money($p['amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="col-lg-4"><div class="card-panel mb-3"><h3 class="h6">Invoice Workflow</h3><form class="ajax-form" method="post" action="<?= url('/invoices/'.$invoice['id'].'/status') ?>"><?= csrf_field() ?><select class="form-select mb-2" name="status"><option <?= $invoice['status']==='Draft'?'selected':'' ?>>Draft</option><option <?= $invoice['status']==='Sent'?'selected':'' ?>>Sent</option><option <?= $invoice['status']==='Cancelled'?'selected':'' ?>>Cancelled</option></select><button class="btn btn-outline-primary w-100">Update Status</button></form></div><?php if((float)$invoice['balance']>0): ?><div class="card-panel"><h3 class="h6">Record Payment</h3><form class="ajax-form" enctype="multipart/form-data" method="post" action="<?= url('/invoices/'.$invoice['id'].'/payment') ?>"><?= csrf_field() ?><label class="form-label">Amount</label><input class="form-control mb-2" type="number" step="0.01" max="<?= e($invoice['balance']) ?>" name="amount" value="<?= e($invoice['balance']) ?>" required><label class="form-label">Date</label><input class="form-control mb-2" type="date" name="payment_date" value="<?= date('Y-m-d') ?>"><label class="form-label">Method</label><select class="form-select mb-2" name="payment_method"><option>Bank Transfer</option><option>Cash</option><option>QRIS</option><option>Credit Card</option><option>Other</option></select><input class="form-control mb-2" name="bank" placeholder="Bank"><input class="form-control mb-2" name="reference" placeholder="Reference"><input class="form-control mb-2" type="file" name="attachment"><textarea class="form-control mb-3" name="notes" placeholder="Notes"></textarea><button class="btn btn-success w-100">Record Payment</button></form></div><?php endif; ?></div></div>
